def simulate_game(n):
    """
    Simulates the game using the greedy strategy (always chooses the smallest valid number).
    Returns (outcome, moves), where outcome is 'Draw', 'Alice_Loss', 'Bob_Loss'.
    """
    chosen = set()
    alice_set = set()
    bob_set = set()
    moves = []
    is_alice_turn = True

    while True:
        current_player = "Alice" if is_alice_turn else "Bob"

        # Determine constraints for the current player (P)
        player_set = alice_set if is_alice_turn else bob_set

        valid_moves = []
        for x in range(1, n + 1):
            if x not in chosen:
                # Rule (ii): Cannot choose a number consecutive to any the player has already chosen
                is_consecutive_to_player_choice = (x - 1 in player_set) or (x + 1 in player_set)
                if not is_consecutive_to_player_choice:
                    valid_moves.append(x)

        if not valid_moves:
            # No moves available
            if len(chosen) == n:
                return "Draw", moves
            else:
                # Current player loses
                return f"{current_player}_Loss", moves

        # Greedy strategy: Choose the smallest valid number
        chosen_move = min(valid_moves)

        # Update state
        chosen.add(chosen_move)
        moves.append((current_player, chosen_move))

        if is_alice_turn:
            alice_set.add(chosen_move)
        else:
            bob_set.add(chosen_move)

        is_alice_turn = not is_alice_turn

    return None, None # Should not happen

print("--- Simulation Results (N=13 to N=30) ---")
for n in range(13, 31):
    outcome, moves = simulate_game(n)

    if outcome == "Draw":
        print(f"N={n}: DRAW. Moves count: {len(moves)}")
    elif outcome == "Alice_Loss":
        print(f"N={n}: Alice Loses (Bob Wins). Moves count: {len(moves)}")
    elif outcome == "Bob_Loss":
        print(f"N={n}: Bob Loses (Alice Wins). Moves count: {len(moves)}")
    else:
        print(f"N={n}: Unexpected outcome.")

